module benchmark/solution

type Tree = Leaf(int) | Node(Tree, int, Tree)

export func mapTree(fn: int -> int, tree: Tree) -> Tree =
  match tree {
    Leaf(v) => Leaf(fn(v)),
    Node(l, v, r) => Node(mapTree(fn, l), fn(v), mapTree(fn, r))
  }

export func foldTree(fn: (int, int) -> int, acc: int, tree: Tree) -> int =
  match tree {
    Leaf(v) => fn(acc, v),
    Node(l, v, r) => foldTree(fn, fn(foldTree(fn, acc, l), v), r)
  }

export func treeToList(tree: Tree) -> [int] =
  match tree {
    Leaf(v) => [v],
    Node(l, v, r) => treeToList(l) ++ [v] ++ treeToList(r)
  }

export func treeDepth(tree: Tree) -> int =
  match tree {
    Leaf(_) => 1,
    Node(l, _, r) => {
      let dl = treeDepth(l);
      let dr = treeDepth(r);
      1 + (if dl > dr then dl else dr)
    }
  }

export func main() -> () ! {IO} {
  let tree = Node(Node(Leaf(1), 2, Leaf(3)), 4, Node(Leaf(5), 6, Leaf(7)));
  println(show(treeToList(tree)));
  println(show(treeToList(mapTree(\x. x * 2, tree))));
  println(show(foldTree(func(a: int, b: int) -> int { a + b }, 0, tree)));
  println(show(treeDepth(tree)))
}

